// ====== 1. 自定义订单门面 ======
// 子系统各自独立，互不感知
public class InventoryService {
    public boolean checkAndLock(Order order) {
        // 校验库存 + 锁定库存
        System.out.println("[Inventory] locked for " + order.getId());
        return true;
    }
}

public class PaymentService {
    public void charge(Order order) {
        // 调用支付网关扣款（微信/支付宝/银行卡）
        System.out.println("[Payment] charged " + order.getAmount());
    }
}

public class ShippingService {
    public void createShipment(Order order) {
        // 创建物流单
        System.out.println("[Shipping] created for " + order.getId());
    }
}

// 门面：只做编排，不放业务 if-else
public class OrderFacade {
    private final InventoryService inventory;
    private final PaymentService payment;
    private final ShippingService shipping;

    public OrderFacade(InventoryService inventory,
                       PaymentService payment,
                       ShippingService shipping) {
        this.inventory = inventory;
        this.payment = payment;
        this.shipping = shipping;
    }

    /** 一次下单的完整编排：锁库存→扣款→创物流 */
    public OrderResult placeOrder(Order order) {
        inventory.checkAndLock(order);  // 步骤 1
        payment.charge(order);          // 步骤 2
        shipping.createShipment(order); // 步骤 3
        return OrderResult.success(order.getId());
    }
}

