// ====== 3. Spring JdbcTemplate 门面 ======
// 封装 Connection/Statement/ResultSet + SQLException→DataAccessException
@Repository
public class UserDao {
    private final JdbcTemplate jdbc;

    public UserDao(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    public User findById(long id) {
        return jdbc.queryForObject(
            "SELECT * FROM users WHERE id = ?",
            (rs, rowNum) -> new User(
                rs.getLong("id"),
                rs.getString("name")
            ),
            id
        );
        // 内部流程：DataSourceUtils.getConnection
        //   → PreparedStatementCreator 创建预编译语句
        //   → setParameter 设参
        //   → execute 执行 → RowMapper 映射
        //   → finally 释放连接
        // SQLException 被翻译为 DataAccessException 子类
    }
}

